style.css:
@-moz-document domain("student.open.ac.uk") {
body {
        background: url('https://i.imgur.com/KFZyT3H.jpg') no-repeat center center fixed; /* Vintage parchment */
        background-size: cover;
        font-family: "Garamond", serif;
        color: #4a3c2f; /* Dark brown text */
    }
    a {
        color: #b1624e; /* Vintage-style links */
        text-decoration: none;
    }
    a:hover {
        color: #8a4b3c; /* Slightly darker on hover */
    }
    header, footer, nav {
        background: rgba(200, 180, 140, 0.9); /* Semi-transparent vintage overlay */
        border: 1px solid #a3876f;
    }
    button, input, select {
        background: #e9d8b4;
        border: 1px solid #a3876f;
        color: #4a3c2f;
    }
    button:hover, input:hover, select:hover {
        background: #d3b98c;
    }
}
